import React, { useContext, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { AuthContext } from "../context/AuthContext";
import "./Navbar.css";

const Navbar = () => {
  const { user, logout } = useContext(AuthContext);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        {/* BRAND */}
        <Link to="/events" className="navbar-brand">
          <span className="logo-icon">📅</span>
          <span className="logo-text">College Events</span>
        </Link>

        {/* MENU */}
        <div className={`navbar-menu ${mobileMenuOpen ? "active" : ""}`}>
          <div className="navbar-nav">
            <Link className="nav-link" to="/events">📍 Events</Link>
            <Link className="nav-link" to="/calendar">📆 Calendar</Link>
            <Link className="nav-link" to="/map">🗺️ Map</Link>

            {user && user.role === "student" && (
              <Link className="nav-link" to="/my-events">⭐ My Events</Link>
            )}

            {user && user.role === "admin" && (
              <Link className="nav-link admin" to="/admin">
                ⚙️ Admin Dashboard
              </Link>
            )}
          </div>

          {/* USER ACTIONS */}
          <div className="navbar-user">
            {user ? (
              <>
                <div className="user-info">
                  <span className="user-name">{user.name}</span>
                  <span className={`user-role ${user.role}`}>{user.role}</span>
                </div>
                <button className="btn-logout" onClick={handleLogout}>
                  Logout
                </button>
              </>
            ) : (
              <>
                <Link className="btn-auth btn-login" to="/login">
                  Sign In
                </Link>
                <Link className="btn-auth btn-register" to="/register">
                  Sign Up
                </Link>
              </>
            )}
          </div>
        </div>

        {/* MOBILE TOGGLE */}
        <button
          className="navbar-toggle"
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
        >
          ☰
        </button>
      </div>
    </nav>
  );
};

export default Navbar;
